-- ============================================================================
-- D1: Oilfield Data Quality joins the catalogue, the FIRST course of the
-- Data & AI module.
--
-- Catalogue row (module 'data_ai'; path_order 66, directly above the HSE
-- module's qra at 65; prereq_slug NULL, the carried-over answer "no hard
-- prerequisite inside a module"; school left at its default, as every
-- Facilities, Economics, Assurance and HSE course leaves it) plus the three
-- capstones and their eighteen graded fields, generated by
-- tools/course-waves/dataqc/gen_course.py from the ENGINE'S OWN RUN
-- (d1_capstone.mjs through the vendored engines/dataai/quality.js), which it
-- refuses to write unless fields.json carries exactly that run's values and
-- the tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/dataqc, because the 78 lessons, the
-- teaching lab (dataqcLab.js), its three explorer panels and the capstone case
-- files ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. Data quality is a set of stated rules applied
-- to a well log or a production series, every flag carrying the rule that
-- fired and its reason, so the course teaches whether the data are fit to use
-- (Associate), which values stand apart and by which measure (Professional)
-- and whether the process that makes the data has changed (Expert), and grades
-- each tier on its own question with numbers the engine returns.
--
-- THE ENGINE. engines/dataai/quality.js, vendored sha-identical with
-- petrolord-engines c7eba2270f (engines #248, #249, #251). Missing is null,
-- undefined or NaN and a sentinel is a present value; limits are definitional
-- and units are never converted; every statistical flag fires strictly beyond
-- its limit; the z-score uses the sample standard deviation; EWMA takes its
-- target and sigma from history and CUSUM needs k and h in stated units.
--
-- WHAT IS GRADED. ODUDU (Associate) grades completeness, coverage, an inferred
-- index step, a liquid-basis water cut, a cumulative drop and a phase-sum
-- allowance; IKORO (Professional) grades a z ceiling case, a modified z, a
-- Tukey fence, a Hampel threshold, a Grubbs critical value and a Mahalanobis
-- distance; AMASIRI (Expert) grades phase-one limits, an EWMA, an exact EWMA
-- limit, a CUSUM and a weighted scorecard. Every value is a return value of the
-- engine, and the data it was run on is in the case files the prompt names.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, a label or
-- a case file, at each field's own shipped tolerance: 0 collisions, and 0
-- pairwise. No prompt states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('dataqc', 'Oilfield Data Quality', 'data_ai', 66, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'dataqc', 'beginner', 'associate',
  'ODUDU-2, a density and neutron log, a SCADA time index and sixty days of production, as delivered',
  'Whether the data are fit to use',
  'ODUDU-2, a development well, and the data delivered with it. Three case files come with this capstone. odudu2_log.csv carries 180 entries of a density and neutron log at a half-foot step, counted from entry 0, with the depth in feet; a missing sample is written null, and the file is left exactly as it was delivered. odudu2_scada_index.csv carries 49 entries of a SCADA time index in minutes, counted from entry 0. odudu2_production.csv carries 60 days of production, day 1 to day 60: oil, water and the gross liquid total in bbl/d, the water cut as reported, and the cumulative oil in bbl, with a lost reading written null. Work at the engine''s defaults unless a setting is stated. Report six values: the completeness of the density column as delivered; the coverage of the interval 6210 to 6280 ft by the neutron column, at a maxStep of 0.5 ft; the expected step the index check infers for the SCADA time index, in minutes; the liquid-basis water cut computed from the rates for day 23; the drop the cumulative check reports, in bbl; and the allowed difference, in bbl/d, on the day the phase-sum check flags. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','odudu_rhob_completeness', 'label','The completeness of the density column as delivered, present over n', 'unit','fraction', 'expected',0.9388888888888889, 'tol',5e-07),
    jsonb_build_object('key','odudu_nphi_coverage', 'label','The coverage of 6210 to 6280 ft by the neutron column at a maxStep of 0.5 ft', 'unit','fraction', 'expected',0.9357142857142857, 'tol',5e-07),
    jsonb_build_object('key','odudu_scada_expected_step_min', 'label','The expected step the index check infers for the SCADA time index', 'unit','minutes', 'expected',14.987899999999996, 'tol',5e-07),
    jsonb_build_object('key','odudu_water_cut_day23', 'label','The liquid-basis water cut computed from the rates for day 23', 'unit','fraction', 'expected',0.33856095258839763, 'tol',5e-07),
    jsonb_build_object('key','odudu_cumulative_drop_bbl', 'label','The drop the cumulative check reports', 'unit','bbl', 'expected',7296.20000000007, 'tol',5e-07),
    jsonb_build_object('key','odudu_phase_sum_allowed_day44_bbl_d', 'label','The allowed difference on the day the phase-sum check flags', 'unit','bbl/d', 'expected',6.7545, 'tol',5e-07)
  )
),
(
  'dataqc', 'intermediate', 'professional',
  'IKORO-5, core plug porosities, a bulk density interval and a density-neutron cloud',
  'Which values stand apart, and by which measure',
  'IKORO-5, a cored appraisal well. Three case files come with this capstone. ikoro5_core_porosity.csv carries 17 core plug porosities in v/v, counted from entry 0. ikoro5_density.csv carries a 80-sample bulk density interval in g/cm3, counted from entry 0, with a missing sample written null. ikoro5_density_neutron.csv carries 36 rows of bulk density and neutron porosity from one sand. Work at the engine''s defaults unless a setting is stated. Report six values: the largest |z| among the core plugs, with the sample standard deviation; the largest |modified z| among the core plugs; the upper Tukey fence of the density interval; the Hampel threshold at entry 57 of the density interval, with a half window of 3 and nSigma 3; the two-sided Grubbs critical value for the core plugs at alpha 0.05; and the largest squared Mahalanobis distance in the density-neutron cloud. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ikoro_core_max_abs_z', 'label','The largest |z| among the core plugs, with the sample standard deviation', 'unit','dimensionless', 'expected',3.0512957006575347, 'tol',5e-07),
    jsonb_build_object('key','ikoro_core_max_abs_modified_z', 'label','The largest |modified z| among the core plugs', 'unit','dimensionless', 'expected',3.556454545454542, 'tol',5e-07),
    jsonb_build_object('key','ikoro_rhob_upper_fence_g_cm3', 'label','The upper Tukey fence of the density interval at the defaults', 'unit','g/cm3', 'expected',2.42485, 'tol',5e-07),
    jsonb_build_object('key','ikoro_rhob_hampel_threshold_entry57_g_cm3', 'label','The Hampel threshold at entry 57 of the density interval', 'unit','g/cm3', 'expected',0.13610267999999884, 'tol',5e-07),
    jsonb_build_object('key','ikoro_core_grubbs_critical', 'label','The two-sided Grubbs critical value for the core plugs at alpha 0.05', 'unit','dimensionless', 'expected',2.619963639834438, 'tol',5e-07),
    jsonb_build_object('key','ikoro_max_mahalanobis_d2', 'label','The largest squared Mahalanobis distance in the density-neutron cloud', 'unit','dimensionless', 'expected',15.548796422055258, 'tol',5e-07)
  )
),
(
  'dataqc', 'advanced', 'expert',
  'AMASIRI-1, a casing pressure in two phases and a scored data sheet',
  'Whether the process has changed, and the score of the sheet',
  'AMASIRI-1, a gas well whose casing pressure is read daily. Two case files come with this capstone. amasiri1_phase_one.csv carries 36 in-control days of casing pressure in psig. amasiri1_phase_two.csv carries 30 monitored days, day 1 to day 30. Chart phase one on an individuals and moving range chart from its own averages, and take phase two''s target and sigma from it: the phase one centre as the target, and sigma as MRbar / 1.128 from the phase one moving ranges. Run phase two on an EWMA chart with lambda 0.2 and L 3, and on a tabular CUSUM with k 0.5 and h 4 in sigma units. The well''s data sheet was scored on five dimensions: completeness 18 failed of 720 checked, validity 9 failed of 702 checked, consistency 23 failed of 690 checked, uniqueness 2 failed of 14 checked, and plausibility 11 failed of 702 checked, weighted 3, 2, 2, 1 and 1 in that order. Report six values: the phase one individuals chart upper limit; the phase one moving range chart upper limit; the EWMA on day 14 of phase two; the exact EWMA upper limit on day 2 of phase two; the upper CUSUM, S_hi, on day 18 of phase two; and the scorecard total at those weights. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','amasiri_phase1_individuals_ucl_psig', 'label','The phase one individuals chart upper limit', 'unit','psig', 'expected',867.6033096926715, 'tol',5e-07),
    jsonb_build_object('key','amasiri_phase1_mr_ucl_psig', 'label','The phase one moving range chart upper limit', 'unit','psi', 'expected',28.161540000000038, 'tol',5e-07),
    jsonb_build_object('key','amasiri_ewma_day14_psig', 'label','The EWMA on day 14 of phase two', 'unit','psig', 'expected',848.7590554998776, 'tol',5e-07),
    jsonb_build_object('key','amasiri_ewma_exact_ucl_day2_psig', 'label','The exact EWMA upper limit on day 2 of phase two', 'unit','psig', 'expected',850.5495789401897, 'tol',5e-07),
    jsonb_build_object('key','amasiri_cusum_upper_day18_psi', 'label','The upper CUSUM, S_hi, on day 18 of phase two', 'unit','psi', 'expected',63.70780141843934, 'tol',5e-07),
    jsonb_build_object('key','amasiri_scorecard_total', 'label','The scorecard total at the stated weights', 'unit','score', 'expected',0.9637961832406277, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
